-- ── media_annotations (Media & AI Recognition) ──
CREATE TABLE media_annotations (
    id uuid NOT NULL DEFAULT uuidv7(),
    blob_id uuid NOT NULL,
    label text NOT NULL,
    confidence numeric(4,3) NOT NULL,
    bbox int4[],
    frame_ms integer,
    product_id uuid,
    model_code text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT media_annotations_pkey PRIMARY KEY (id),
    CONSTRAINT media_annotations_chk1 CHECK (bbox IS NULL OR cardinality(bbox) = 4),
    CONSTRAINT media_annotations_chk2 CHECK (confidence BETWEEN 0 AND 1)
);
COMMENT ON TABLE media_annotations IS 'AI labels on a file (label, confidence, bbox, video frame), optionally resolved to a product.';
COMMENT ON COLUMN media_annotations.bbox IS '[x, y, w, h] px';

-- ── embedding_models (Media & AI Recognition) ──
CREATE TABLE embedding_models (
    code text NOT NULL,
    modality embedding_modality NOT NULL,
    dimensions integer NOT NULL,
    is_active boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT embedding_models_pkey PRIMARY KEY (code),
    CONSTRAINT embedding_models_chk1 CHECK (dimensions BETWEEN 1 AND 16000)
);
COMMENT ON TABLE embedding_models IS 'Registry of embedding models and their dimensions (CLIP ViT-L/14 = 768, Titan v2 = 1024…).';

-- ── media_embeddings (Media & AI Recognition) ──
CREATE TABLE media_embeddings (
    blob_id uuid NOT NULL,
    model_code text NOT NULL,
    embedding vector NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT media_embeddings_pkey PRIMARY KEY (blob_id, model_code)
);
COMMENT ON TABLE media_embeddings IS 'Image embeddings per model for visual similarity search.';
COMMENT ON COLUMN media_embeddings.embedding IS 'dims checked against embedding_models (trigger)';

-- ── product_traceability (Sources, Ingestion & Evidence) ──
CREATE TABLE product_traceability (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    attribute text NOT NULL,
    value text NOT NULL,
    evidence_id uuid NOT NULL,
    match_method text NOT NULL,
    confidence numeric(4,3),
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_traceability_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE product_traceability IS 'Resolved product facts (manufacturer, model, specs) with evidence and method — the permanent ''why we believe this''.';
COMMENT ON COLUMN product_traceability.attribute IS 'manufacturer | model | spec:<key>';
COMMENT ON COLUMN product_traceability.match_method IS 'gtin_exact | brand_model | ai_assisted';

-- ── recall_embeddings (Recalls) ──
CREATE TABLE recall_embeddings (
    recall_id uuid NOT NULL,
    model_code text NOT NULL,
    content_sha256 bytea NOT NULL,
    embedding vector NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT recall_embeddings_pkey PRIMARY KEY (recall_id, model_code)
);
COMMENT ON TABLE recall_embeddings IS 'Semantic vectors of recall text per model (hybrid BM25 + kNN retrieval).';
COMMENT ON COLUMN recall_embeddings.content_sha256 IS 're-embed only when text changes';

-- ── product_embeddings (Product Catalogue (Registry)) ──
CREATE TABLE product_embeddings (
    product_id uuid NOT NULL,
    model_code text NOT NULL,
    content_sha256 bytea NOT NULL,
    embedding vector NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT product_embeddings_pkey PRIMARY KEY (product_id, model_code)
);
COMMENT ON TABLE product_embeddings IS 'Semantic vector of a product''s identity and known safety facts, per model.';
COMMENT ON COLUMN product_embeddings.content_sha256 IS 're-embed only when the text changes';

-- ── evidence_embeddings (Sources, Ingestion & Evidence) ──
CREATE TABLE evidence_embeddings (
    evidence_id uuid NOT NULL,
    model_code text NOT NULL,
    embedding vector NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT evidence_embeddings_pkey PRIMARY KEY (evidence_id, model_code)
);
COMMENT ON TABLE evidence_embeddings IS 'Semantic vector of one evidence item''s excerpt (finding, recall, review, flag), per model.';

-- ── scoring_contexts (Screening, Hazard & Passport) ──
CREATE TABLE scoring_contexts (
    code text NOT NULL,
    name text NOT NULL,
    alert_threshold numeric(5,2) NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    CONSTRAINT scoring_contexts_pkey PRIMARY KEY (code),
    CONSTRAINT scoring_contexts_chk1 CHECK (alert_threshold BETWEEN 0 AND 100)
);
COMMENT ON TABLE scoring_contexts IS 'Scoring frameworks (safety now; sustainability/circularity later) and their alert threshold.';

-- ── scoring_bands (Screening, Hazard & Passport) ──
CREATE TABLE scoring_bands (
    context_code text NOT NULL,
    label text NOT NULL,
    score_range numrange NOT NULL,
    action text NOT NULL,
    CONSTRAINT scoring_bands_pkey PRIMARY KEY (context_code, label),
    CONSTRAINT scoring_bands_chk1 CHECK (NOT isempty(score_range)),
    CONSTRAINT scoring_bands_chk2 CHECK (score_range <@ numrange(0, 100, '[]'))
);
COMMENT ON TABLE scoring_bands IS 'Score → label → action bands per context; ranges may not overlap.';
COMMENT ON COLUMN scoring_bands.score_range IS 'e.g. [0,30)';
COMMENT ON COLUMN scoring_bands.action IS 'approve | manual_review | block';

-- ── hazard_dimensions (Screening, Hazard & Passport) ──
CREATE TABLE hazard_dimensions (
    code text NOT NULL,
    context_code text NOT NULL,
    name text NOT NULL,
    description text,
    weight numeric(4,2) NOT NULL,
    sort_order smallint NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    CONSTRAINT hazard_dimensions_pkey PRIMARY KEY (code),
    CONSTRAINT hazard_dimensions_code_context_code_key UNIQUE (code, context_code),
    CONSTRAINT hazard_dimensions_chk1 CHECK (weight > 0),
    CONSTRAINT hazard_dimensions_chk2 CHECK (code LIKE context_code || '.%')
);
COMMENT ON TABLE hazard_dimensions IS 'Configurable scoring dimensions and weights. Codes are namespaced by context (safety.regulatory…).';

-- ── hazard_assessments (Screening, Hazard & Passport) ──
CREATE TABLE hazard_assessments (
    id uuid NOT NULL DEFAULT uuidv7(),
    product_id uuid NOT NULL,
    context_code text NOT NULL,
    total_score numeric(5,2),
    label text,
    input_modalities text[] NOT NULL,
    has_insufficient_data boolean NOT NULL DEFAULT false,
    model_code text NOT NULL,
    prompt_version text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT hazard_assessments_pkey PRIMARY KEY (id),
    CONSTRAINT hazard_assessments_id_product_id_key UNIQUE (id, product_id),
    CONSTRAINT hazard_assessments_id_context_code_key UNIQUE (id, context_code),
    CONSTRAINT hazard_assessments_chk1 CHECK (total_score BETWEEN 0 AND 100),
    CONSTRAINT hazard_assessments_chk2 CHECK (input_modalities <@ ARRAY['text','image','video']::text[] AND cardinality(input_modalities) > 0)
);
COMMENT ON TABLE hazard_assessments IS 'One multimodal hazard scoring run (weighted total, label, model).';

-- ── hazard_dimension_scores (Screening, Hazard & Passport) ──
CREATE TABLE hazard_dimension_scores (
    assessment_id uuid NOT NULL,
    context_code text NOT NULL,
    dimension_code text NOT NULL,
    status dimension_score_status NOT NULL,
    score numeric(5,2),
    weight_applied numeric(4,2) NOT NULL,
    justification text,
    CONSTRAINT hazard_dimension_scores_pkey PRIMARY KEY (assessment_id, dimension_code),
    CONSTRAINT hazard_dimension_scores_chk1 CHECK ((status = 'scored') = (score IS NOT NULL)),
    CONSTRAINT hazard_dimension_scores_chk2 CHECK (score BETWEEN 0 AND 100),
    CONSTRAINT hazard_dimension_scores_chk3 CHECK (weight_applied > 0)
);
COMMENT ON TABLE hazard_dimension_scores IS 'Per-dimension score + justification. Scored ⇒ ≥1 citation (deferred trigger); uncited ⇒ insufficient_data with NULL score.';
COMMENT ON COLUMN hazard_dimension_scores.context_code IS 'must equal the assessment''s and the dimension''s context';

-- ── hazard_score_citations (Screening, Hazard & Passport) ──
CREATE TABLE hazard_score_citations (
    assessment_id uuid NOT NULL,
    dimension_code text NOT NULL,
    evidence_id uuid NOT NULL,
    CONSTRAINT hazard_score_citations_pkey PRIMARY KEY (assessment_id, dimension_code, evidence_id)
);
COMMENT ON TABLE hazard_score_citations IS 'Evidence cited for each dimension score.';

-- ── chat_threads (Community & Reviews) ──
CREATE TABLE chat_threads (
    id uuid NOT NULL DEFAULT uuidv7(),
    user_id uuid NOT NULL,
    product_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_message_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT chat_threads_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE chat_threads IS 'A member''s conversation with the product assistant about one product (its memory).';

-- ── chat_messages (Community & Reviews) ──
CREATE TABLE chat_messages (
    id uuid NOT NULL DEFAULT uuidv7(),
    thread_id uuid NOT NULL,
    role text NOT NULL,
    content text NOT NULL,
    citations jsonb NOT NULL DEFAULT '[]'::jsonb,
    model_code text,
    prompt_version text,
    input_tokens integer,
    output_tokens integer,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT chat_messages_pkey PRIMARY KEY (id),
    CONSTRAINT chat_messages_chk1 CHECK (role IN ('user', 'assistant')),
    CONSTRAINT chat_messages_chk2 CHECK (char_length(content) BETWEEN 1 AND 8000)
);
COMMENT ON TABLE chat_messages IS 'One turn of a conversation. An answer keeps the evidence it cited and the model that wrote it.';
COMMENT ON COLUMN chat_messages.citations IS '[{evidence_id, url, excerpt}]';

-- ── review_tasks (Platform, Audit & Operations) ──
CREATE TABLE review_tasks (
    id uuid NOT NULL DEFAULT uuidv7(),
    task_type review_task_type NOT NULL,
    subject_type text NOT NULL,
    subject_id uuid NOT NULL,
    status review_task_status NOT NULL DEFAULT 'open',
    priority smallint NOT NULL DEFAULT 3,
    submitted_by_user_id uuid,
    payload jsonb NOT NULL DEFAULT '{}',
    assigned_to_user_id uuid,
    resolution text,
    resolved_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT review_tasks_pkey PRIMARY KEY (id),
    CONSTRAINT review_tasks_chk1 CHECK (priority BETWEEN 1 AND 5),
    CONSTRAINT review_tasks_chk2 CHECK ((status IN ('resolved','dismissed')) = (resolved_at IS NOT NULL))
);
COMMENT ON TABLE review_tasks IS 'Unified human-review queue; user-submitted material (e.g. manual certification evidence) in payload.';

-- ── ai_invocations (Platform, Audit & Operations) ──
CREATE TABLE ai_invocations (
    id uuid NOT NULL DEFAULT uuidv7(),
    purpose ai_purpose NOT NULL,
    model_code text NOT NULL,
    prompt_version text,
    user_id uuid,
    subject_type text,
    subject_id uuid,
    input_tokens integer,
    output_tokens integer,
    cost_usd numeric(10,6),
    latency_ms integer,
    succeeded boolean NOT NULL,
    error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ai_invocations_pkey PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE ai_invocations IS 'Every model call: purpose, model, tokens, cost, latency — quotas, budgets, evals. Monthly partitions.';

-- ── outbox_events (Platform, Audit & Operations) ──
CREATE TABLE outbox_events (
    id uuid NOT NULL DEFAULT uuidv7(),
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    event_type text NOT NULL,
    payload jsonb NOT NULL,
    published_at timestamptz,
    attempts smallint NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT outbox_events_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE outbox_events IS 'Transactional outbox: events written with the change, published afterwards.';

